import { Injectable } from '@angular/core';
import { OrderDispatchList } from '../pages/order-dispatch-list/order-dispatch-list';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { environment } from '../environments/environments';
@Injectable({
  providedIn: 'root'
})
export class OrderService {
 private ApiUrl = `${environment.apiUrl}/OrderDispatch/`;

  constructor(private http: HttpClient) {}

  getOrders(): Observable<OrderDispatchList[]>{
    return this.http.get<OrderDispatchList[]>(`${this.ApiUrl}`);
  }

  CreateOrders(Orders: OrderDispatchList): Observable<OrderDispatchList> {
  return this.http.post<OrderDispatchList>(`${this.ApiUrl}create`, Orders);
}
  getOrdersById(id: number): Observable<OrderDispatchList> {
  return this.http.get<OrderDispatchList>(`${this.ApiUrl}${id}`);
}

  editOrders(id: number, Orders: OrderDispatchList): Observable<OrderDispatchList> {
  return this.http.put<OrderDispatchList>(`${this.ApiUrl}update/${id}`, Orders);
}
getOrdersByStatus(status: number): Observable<OrderDispatchList[]> {
  return this.http.get<OrderDispatchList[]>(`${this.ApiUrl}by-status/${status}`)
}
}